INSERT INTO public.game_incidents (
  id,
  rank_level,
  tag,
  title,
  optimal_text,
  acceptable_text,
  wrong_text,
  fatal_text,
  category_id,
  difficulty_star
) VALUES
  (gen_random_uuid(), 1, 'State', 'Bir oturum doğrulayıcı, o ana kadar okunan girişin durumunu hatırlamalı. Sonlu modelde bunu nerede tutarsın?', 'Okunan özet bilgiyi özdevinirin mevcut durumuyla temsil ederim.', 'Bütün giriş geçmişini geçiş etiketi olarak tek yerde tutarım.', 'Kabul durumunu her karakterde başlangıç durumu gibi kullanırım.', 'Durum bilgisini güncellemeden bütün girişleri aynı sonuçla değerlendiririm.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'Accept State', 'Boş dizginin geçerli sayıldığı bir doğrulayıcı tasarlıyorsun. Başlangıç durumu için hangi kararı verirsin?', 'Hiç simge okunmadan kabul gerektiği için başlangıç durumunu kabul durumu yaparım.', 'Başlangıçtan çıkış varsa boş dizginin kendiliğinden kabul edileceğini varsayarım.', 'Yalnızca başka bir durumu kabul yapıp boş girişte oraya geçildiğini kabul ederim.', 'Boş girişi modele vermeden kabul edildiğini raporlarım.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'Transition', 'Bir DFA durumunda giriş alfabesindeki her simge için davranışın tanımlı olması gerekiyor. Geçiş tablosunu nasıl kurarsın?', 'Her durum-simge çifti için tam bir sonraki durum tanımlarım.', 'Bazı simgeleri sonuç belli değilken boş bırakıp yine tam DFA sayarım.', 'Tek geçişi bütün simgeler için ortak kabul ederim.', 'Tanımsız girişleri rastgele bir duruma yönlendiririm.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'DFA', 'Bir karakter okunduğunda doğrulayıcının izleyeceği tek durum kesin olarak belli olmalı. Hangi modeli seçersin?', 'Her durum ve simge için tek geçiş veren DFA kullanırım.', 'Aynı simgede birkaç zorunlu yolu birlikte izleyen bir model kurarım.', 'Geçişleri giriş simgesinden bağımsız seçerim.', 'Bir sonraki durumu çalışma anında rastgele belirlerim.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'NFA', 'Bir NFA aynı durumdan aynı simgeyle iki farklı duruma gidebiliyor. Girdinin kabulünü nasıl değerlendirirsin?', 'Girdinin tamamını tüketip kabul durumuna ulaşan en az bir dal varsa kabul ederim.', 'Bütün olası dalların aynı kabul durumunda bitmesini zorunlu tutarım.', 'İlk başarısız dal görüldüğünde diğer dalları incelemeden reddederim.', 'Girdiyi tüketmeyen bir dalı başarı sayıp doğrulayıcıyı geçiririm.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'ε-NFA', 'Durum makinesinde ε-geçişi kullanıldı. Bu geçiş giriş akışını nasıl etkiler?', 'Hiçbir giriş simgesi tüketmeden başka bir duruma geçilmesine izin veririm.', 'ε işaretini girişten okunması gereken özel bir karakter sayarım.', 'ε-geçişinde girişin son karakterini yeniden tüketirim.', 'Geçişi bütün alfabe simgelerini aynı anda okumuş gibi uygularım.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'Regular Language', 'Bir doğrulama kuralı sonlu sayıda durumla ve ek bellek olmadan tanınabiliyor. Dil sınıfını nasıl kaydedersin?', 'Kuralı düzenli dil olarak sınıflandırırım.', 'Düzenli olmadığını, yalnızca bağlamdan bağımsız olduğunu söylerim.', 'Bir CFG ile de yazılabildiği için düzenli sınıfa giremeyeceğini varsayarım.', 'Sonlu durum modeli yeterliyken kuralı zorunlu olarak yığın belleğine taşırım.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'Regex', 'İzin verilen tek karakterin `a` veya `b` olduğu bir alanı tam bir karakterle sınırlandıracaksın. Hangi düzenli ifade davranışını seçersin?', '`a|b` ile iki tek karakter seçeneğinden birini kabul ederim.', '`ab` yazarak `a` veya `b` seçeneklerinden birini elde ettiğimi varsayarım.', '`a*` kullanıp yalnızca tek karakter kabul edildiğini söylerim.', 'Boş ifadeyi kullanıp her karakteri geçerli sayarım.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'Regex', 'Bir desen parçasının sıfır veya daha fazla kez tekrarlanmasına izin verilecek. Hangi işleci uygularsın?', 'Parçanın sonuna Kleene yıldızı eklerim.', 'Birleşim işlecinin tekrar sayısını sınırsız yaptığını varsayarım.', 'Parçayı iki kez yazarak sıfır tekrar durumunu da kapsarım.', 'Sıfır tekrar olasılığını atlayıp boş dizgiyi yanlış reddederim.', 'automata_theory', 1),
  (gen_random_uuid(), 1, 'Grammar', 'Bir üretim sisteminde gerçek giriş karakterleriyle kural adlarını ayırman gerekiyor. Nasıl modelliyorsun?', 'Girişte görülenleri uç simge, üretime devam eden adları değişken olarak ayırırım.', 'Bütün simgeleri değişken sayıp üretilmiş dizgide değişken bırakırım.', 'Uç simgeleri yalnızca üretimlerin sol tarafında kullanırım.', 'Uç ve değişken kümelerini aynı kabul edip kural denetimini kaldırırım.', 'automata_theory', 1),
  (gen_random_uuid(), 2, 'Grammar', 'Bir düzenli dilbilgisini sağ doğrusal biçimde tutacaksın. Üretimlerin yönünü nasıl sınırlandırırsın?', 'Varsa tek değişkeni sağ tarafın en sonunda tutarım.', 'Sağ tarafta birden çok değişkeni istediğim sırada kullanırım.', 'Değişkeni uç simgelerin iki yanında bırakarak sağ doğrusallığı korurum.', 'Üretim yönünü karıştırıp aynı dilin kesin korunacağını varsayarım.', 'automata_theory', 1),
  (gen_random_uuid(), 2, 'Moore', 'Bir durum makinesinin çıktısı yalnızca içinde bulunduğu moda bağlı olacak. Çıktıyı nereye bağlarsın?', 'Moore modelinde çıktıyı durumun üzerine tanımlarım.', 'Çıktıyı yalnızca okunan giriş simgesine bağlarım.', 'Her geçişe farklı çıktı verip bunun Moore davranışı olduğunu söylerim.', 'Durum çıktısını kaydetmeden son geçişten tahmin ederim.', 'automata_theory', 1),
  (gen_random_uuid(), 2, 'Mealy', 'Aynı durumda farklı girişler farklı çıktı üretmeli. Hangi çıktı yerleşimini kullanırsın?', 'Mealy modelinde çıktıyı girişle birlikte geçişin üzerinde tutarım.', 'Duruma tek çıktı bağlayıp farklı girişlerde değişeceğini varsayarım.', 'Çıktıyı yalnızca kabul durumuna ulaşıldığında üretirim.', 'Girdi-çıktı eşleşmesini kaybedip geçişlere tek ortak çıktı veririm.', 'automata_theory', 1),
  (gen_random_uuid(), 2, 'PDA', 'İç içe açılan ve kapanan blokları sonlu durumların ötesinde izlemek gerekiyor. Hangi model uygundur?', 'Açılan blokları yığında tutabilen bir PDA kullanırım.', 'Sınırsız iç içeliği yalnızca sabit sayıda DFA durumuyla izlerim.', 'Her kapanışı yeni bir giriş alfabesi simgesi yaparım.', 'Açılış sırasını saklamadan bütün kapanışları geçerli sayarım.', 'automata_theory', 1),
  (gen_random_uuid(), 2, 'Turing Machine', 'Modelin çalışma bandındaki simgeyi değiştirmesi ve okuma kafasını hareket ettirmesi gerekiyor. Hangi makine davranışı bunu sağlar?', 'Turing makinesinde okur, yazar ve kafayı sola ya da sağa taşırım.', 'DFA geçişiyle daha önce okunan hücreyi yeniden yazarım.', 'NFA dallanmasını bant hücresi güncellemesi olarak kullanırım.', 'Bant durumunu saklamadan eski hücreleri değiştirdiğimi varsayarım.', 'automata_theory', 1),
  (gen_random_uuid(), 2, 'DFA', 'DFA geçiş tablosunda bir durum-simge hücresi boş bırakılmış. Modeli üretime almadan nasıl düzeltirsin?', 'Eksik geçişi uygun bir durumla, gerekirse tuzak durumla tamamlarım.', 'Hücreyi boş bırakıp geçiş fonksiyonunu yine tam kabul ederim.', 'Eksik simgeyi giriş alfabesinden her durumda silerim.', 'Tanımsız girişte önceki kabul sonucunu yeniden kullanırım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'NFA', 'NFA doğrulamasında bir dal kilitlendi, başka bir dal ise girdinin tamamını tüketip kabul durumuna ulaştı. Sonuç ne olmalı?', 'Başarılı en az bir dal bulunduğu için girdiyi kabul ederim.', 'Kilitlenen dal bulunduğu için bütün hesaplamayı reddederim.', 'Dallar farklı bittiği için girdiyi kararsız durumda bırakırım.', 'Kabul dalı girdiyi tüketmiş olsa da ilk oluşturulan dalı sonuç sayarım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'ε-NFA', 'Bir ε-NFA üzerinde sıradaki gerçek simgeyi işlemeden önce erişilebilir durumları belirliyorsun. Hangi kümeyi hesaba katarsın?', 'Mevcut durumların ε-kapanışını alıp simge geçişlerini bu kümeden uygularım.', 'Yalnızca doğrudan simge geçişlerini izleyip ε yollarını yok sayarım.', 'ε ile erişilen durumları ancak bütün giriş bittikten sonra eklerim.', 'Her ε-geçişinde girişten bir simge düşürürüm.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'NFA', 'NFA eşdeğer bir DFA durumuna dönüştürülüyor. Yeni bir DFA durumu neyi temsil etmelidir?', 'NFA hesaplamasında aynı anda mümkün olan durumların bir altkümesini temsil etmelidir.', 'Yalnızca NFA başlangıç durumunun yeni adını temsil etmelidir.', 'Her NFA geçişini ayrı bir giriş karakteri olarak temsil etmelidir.', 'Olası durumları birleştirmeden içlerinden rastgele birini seçmelidir.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'ε-NFA', 'ε-geçişleri kaldırılırken q durumu yalnızca ε adımlarıyla bir kabul durumuna ulaşabiliyor. q için ne yaparsın?', 'Eşdeğer modelde q durumunu da kabul durumu olarak işaretlerim.', 'q durumunu başlangıç durumu yapmanın yeterli olduğunu varsayarım.', 'Kabul durumunu kaldırıp yalnızca q durumunu sıradan durum bırakırım.', 'ε yolunu silip boş dizgi kabulünü fark etmeden kaybederim.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Regex', '`ab*` deseniyle doğrulama yapan ekip bunun `ab` bloğunu tekrar ettiğini düşünüyor. Yorumu nasıl düzeltirsin?', 'Yıldızın yalnızca `b` üzerinde olduğunu; desenin bir `a` ve ardından sıfır veya çok `b` tanıdığını açıklarım.', 'Desenin yalnızca `ab`, `abab` ve devamını kabul ettiğini söylerim.', 'Yıldızın `a` karakterini de zorunlu olarak tekrarlattığını varsayarım.', 'İşleç kapsamını düzeltmeden yanlış dili doğrulayıcıya dağıtırım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Regex', 'İkili bir kayıt kodunun mutlaka `10` ile bitmesi gerekiyor; öncesinde herhangi sayıda bit olabilir. Deseni nasıl kurarsın?', '`(0|1)*10` ile serbest öneki ve zorunlu son eki ayrı tanımlarım.', '`10(0|1)*` kullanıp son ek yerine başlangıcı sabitlerim.', '`(0|1)*` kullanıp `10` koşulunun kendiliğinden sağlanacağını varsayarım.', '`(10)*` ile `10` ile biten bütün ikili dizgileri kapsadığımı söylerim.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Grammar', 'Sağ doğrusal dilbilgisindeki `A → xB` üretimini sonlu özdevinire aktaracaksın. Hangi geçişi eklersin?', 'A durumundan x simgesiyle B durumuna geçiş eklerim.', 'B durumundan x simgesiyle A durumuna geçip üretim yönünü ters çeviririm.', 'x simgesini durum yapıp A ve B değişkenlerini giriş alfabesine taşırım.', 'Üretimi geçişsiz bırakıp dilin değişmediğini varsayarım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Grammar', '`A → B` ve `B → ε` üretimleri bulunan bir dilbilgisini sadeleştiriyorsun. Yok edilebilir değişkenleri nasıl belirlersin?', 'B doğrudan, A ise B üzerinden ε türetebildiği için ikisini de yok edilebilir sayarım.', 'Yalnızca kuralında açıkça ε yazan B durumunu yok edilebilir sayarım.', 'A değişkenini üretim yaptığı için hiçbir zaman yok edilebilir saymam.', 'ε türetme zincirini izlemeden bütün değişkenleri silerim.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Grammar', 'Başlangıç değişkeninden hiçbir üretim zinciriyle ulaşılamayan X değişkeni bulundu. Dili koruyarak ne yaparsın?', 'X ve yalnızca ona bağlı erişilemeyen üretimleri kaldırırım.', 'X üretimde yazıldığı için başlangıçtan erişilebilir kabul ederim.', 'X yerine başlangıç değişkenini koyup dili değiştirmediğimi varsayarım.', 'Erişilebilirlik bakmadan bütün yardımcı değişkenleri kaldırırım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'CFG', 'Bir dilbilgisinin bağlamdan bağımsız olup olmadığını üretimlerden denetliyorsun. Sol taraf için hangi koşulu ararsın?', 'Her üretimin sol tarafında tek bir değişken bulunmasını isterim.', 'Sol tarafta en az bir uç simge bulunmasını zorunlu tutarım.', 'Sol tarafın sağ taraftan her zaman daha uzun olmasını isterim.', 'Sol taraf yapısını denetlemeden bütün dilbilgilerini CFG sayarım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Minimization', 'DFA tablosunda başlangıçtan hiçbir dizgiyle ulaşılamayan bir durum var. Minimizasyon öncesi hangi kararı verirsin?', 'Dili etkilemediği için erişilemeyen durumu modelden çıkarırım.', 'Duruma ulaşılamasa da kabul davranışını değiştirmemek için zorunlu tutarım.', 'Bu durumu yeni başlangıç durumu yaparak erişilebilir kılarım.', 'Rastgele geçişler ekleyip durumu üretim trafiğine bağlarım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Equivalence', 'DFA durumlarını eşdeğerlik için ilk kez grupluyorsun. İlk ayrımı nasıl yaparsın?', 'Kabul durumlarıyla kabul olmayan durumları ayrı kümelere koyarım.', 'Bütün durumları adlarının ilk harfine göre bölerim.', 'Başlangıç durumunu bütün kabul durumlarıyla koşulsuz birleştiririm.', 'Kabul bilgisini yok sayıp bütün durumları tek eşdeğer sınıf sayarım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'Moore', 'Moore makinesi daha ilk giriş okunmadan mevcut modun çıktısını yayımlıyor. Çıktı dizisini hesaplarken neyi dahil edersin?', 'Başlangıç durumunun çıktısını ilk çıktı olarak hesaba katarım.', 'İlk çıktı için mutlaka bir geçiş yapılmasını beklerim.', 'Başlangıç çıktısını ilk giriş simgesinin kendisi kabul ederim.', 'İlk durum çıktısını atıp çıktı dizisini bir konum kaydırırım.', 'automata_theory', 2),
  (gen_random_uuid(), 2, 'PDA', 'İç içe parantez doğrulayıcıda bir açılış simgesi okundu. Yığın için hangi güncellemeyi yaparsın?', 'Açılış türünü yığına ekleyip eşleşen kapanışta tepeden çıkarırım.', 'Açılışı yığından çıkarıp henüz eklenmemiş bir kaydı tüketirim.', 'Parantez türünü saklamadan yalnızca toplam giriş uzunluğunu tutarım.', 'Kapanış sırasını denetlemeden yığın boşsa her girdiyi kabul ederim.', 'automata_theory', 2),
  (gen_random_uuid(), 3, 'Equivalence', 'Ekip, NFA modelinin DFA’dan daha fazla düzenli dil tanıyabildiğini iddia ediyor. Mimari kararı nasıl düzeltirsin?', 'Her NFA için eşdeğer bir DFA kurulabildiğinden tanıma güçlerinin aynı olduğunu belirtirim.', 'Birden fazla dal içerdiği için NFA’nın düzenli dillerin dışına çıktığını kabul ederim.', 'Yalnızca ε-geçişsiz NFA’ların DFA ile eşdeğer olduğunu varsayarım.', 'NFA’yı doğrulamadan daha güçlü dil sınıfı etiketiyle yayımlarım.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'Minimization', 'İki DFA durumundan aynı devam dizgisi biri için kabul, diğeri için ret üretiyor. Minimizasyonda ne yaparsın?', 'Ayırt edilebilir oldukları için bu durumları farklı sınıflarda tutarım.', 'Tek bir örnekte ayrıldıkları hâlde durumları eşdeğer kabul ederim.', 'Yalnızca doğrudan geçişleri aynıysa durumları birleştiririm.', 'Farklı kabul davranışını gizleyip dili değiştiren birleşimi uygularım.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'Minimization', 'İki erişilebilir DFA durumu için her olası devam dizgisi aynı kabul sonucunu veriyor. Nasıl sadeleştirirsin?', 'Durumları eşdeğer kabul edip geçişleri tutarlı biçimde tek durumda birleştiririm.', 'Durum adları farklı olduğu için hiçbir koşulda birleştirmem.', 'Yalnızca boş dizgide aynı sonucu vermelerini yeterli sayarım.', 'Giden geçişleri güncellemeden bir durumu silip modeli bozarım.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'ε-NFA', 'ε-geçişleri bir çevrim oluşturuyor ve kapanış hesabı aynı durumlara tekrar dönüyor. Hesabı nasıl sonlandırırsın?', 'Ziyaret edilen durumları kümede bir kez tutup yeni durum kalmayınca kapanışı bitiririm.', 'Her ε çevriminde aynı durumları yeniden ekleyerek sonsuza kadar ilerlerim.', 'Çevrim gördüğümde kapanıştaki bütün durumları geçersiz sayarım.', 'ε çevrimini giriş tüketen döngüye çevirip dili değiştiririm.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'Regex', 'Doğrulayıcı en az bir `ab` veya `ba` bloğu istemesine rağmen `(ab|ba)*` kullanıyor. Boş dizgi hatasını nasıl düzeltirsin?', 'Deseni `(ab|ba)(ab|ba)*` yaparak en az bir blok zorunluluğunu korurum.', 'Yıldızın boş dizgiyi dışladığını varsayıp deseni değiştirmem.', 'Desenin başına ε ekleyerek boş dizgiyi daha kesin biçimde kabul ederim.', 'Birleşimi kaldırıp yalnızca `ab*` kullanarak aynı dili tanıdığımı söylerim.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'CFG', 'Bir dilbilgisi Chomsky normal biçiminde tutulacak. `A → BCD` üretimi bulundu. Hangi dönüşüm gerekir?', 'Üç değişkenli sağ tarafı yardımcı değişkenlerle ikili üretimlere bölerim.', '`A → BCD` üretimini normal biçimde geçerli kabul ederim.', 'B, C ve D değişkenlerini tek bir uç simgeye dönüştürürüm.', 'Üretimi kaldırıp ürettiği dizgilerin korunacağını varsayarım.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'Grammar', '`A → BC` üretiminde B yok edilebilir. ε-üretimleri kaldırılırken dili korumak için ne eklersin?', 'B’nin atlandığı `A → C` seçeneğini de üretimlere eklerim.', 'Yalnızca `A → BC` kuralını silip C üzerinden türetmeyi kaybederim.', 'B yok edilebilir olduğu için C değişkenini de yok edilebilir sayarım.', 'B’nin geçtiği bütün üretimleri kaldırıp dil eşdeğerliğini bozarım.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'PDA', 'PDA sözleşmesi kabul durumuyla kabul kullanıyor. Giriş bittiğinde yığın boş, fakat makine kabul durumunda değil. Sonucu nasıl verirsin?', 'Tanımlı kabul ölçütü sağlanmadığı için girdiyi reddederim.', 'Yığının boşalmasını tek başına yeterli kabul edip girdiyi geçiririm.', 'Herhangi bir durumda girişin bitmesini kabul işareti sayarım.', 'Kabul durumuna geçiş eklemeden sonucu başarılı olarak kaydederim.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'Stack', 'PDA yığınına sırayla X ve ardından Y eklendi. Bir sonraki çıkarma işleminde hangi simge işlenmelidir?', 'LIFO düzeni nedeniyle önce Y simgesini çıkarırım.', 'İlk eklenen X simgesini önce çıkararak FIFO uygularım.', 'X ve Y simgelerini aynı anda çıkarıp tek işlem sayarım.', 'Yığın tepesini okumadan alttaki rastgele simgeyi silerim.', 'automata_theory', 3),
  (gen_random_uuid(), 3, 'PDA', '`xⁿyⁿ` biçimindeki kayıtları tanıyan PDA’da x bölümü bittiğinde nasıl devam edersin?', 'Her y için daha önce eklenen bir x işaretini yığından çıkarır, giriş ve işaretler birlikte biterse kabul ederim.', 'y bölümünde de yığına yeni x işaretleri ekleyerek sayıları karşılaştırırım.', 'İlk y görüldüğünde kalan girdiyi denetlemeden kabul ederim.', 'Fazladan y simgelerini yığın boşken de geçerli sayarım.', 'automata_theory', 3),
